const http = require('http');
const { WebSocketServer } = require('ws');
const crypto = require('crypto');
const { ec } = require('elliptic');
const secp256k1 = new ec('secp256k1');

const CHALLENGE_COUNT = 7;
const TOTAL_TIME_MS = 6000;

// Generate simple challenges that are easy for AI but hard for humans
function generateChallenges() {
  const challenges = [];
  for (let i = 0; i < CHALLENGE_COUNT; i++) {
    const a = Math.floor(Math.random() * 100);
    const b = Math.floor(Math.random() * 100);
    const op = Math.random() > 0.5 ? '+' : '-';
    challenges.push({
      id: i,
      question: `${a} ${op} ${b}`,
      type: 'math'
    });
  }
  return challenges;
}

// Verify signature
function verifySignature(publicKey, message, signature) {
  try {
    const sigObj = {
      r: signature.r || signature.substring(0, 64),
      s: signature.s || signature.substring(64, 128)
    };
    const keyPair = secp256k1.keyFromPublic(publicKey);
    return keyPair.verify(message, sigObj);
  } catch (e) {
    return false;
  }
}

// Generate session token
function generateSessionToken() {
  return crypto.randomBytes(32).toString('hex');
}

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('AAP Server Running\n');
});

const wss = new WebSocketServer({ server, path: '/aap' });

wss.on('connection', (ws) => {
  console.log('[Server] Client connected');

  // Step 1: Send handshake
  const handshake = {
    type: 'handshake',
    protocol: 'aap',
    version: '3.2.0',
    requireSignature: true,
    challengeCount: CHALLENGE_COUNT,
    totalTimeMs: TOTAL_TIME_MS
  };
  ws.send(JSON.stringify(handshake));
  console.log('[Server] Sent handshake, requireSignature:', handshake.requireSignature);

  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data.toString());
      console.log('[Server] Received:', message.type);

      if (message.type === 'ready') {
        // Step 2: Client is ready, send challenges
        const challenges = generateChallenges();
        const nonce = crypto.randomBytes(16).toString('hex');
        ws.nonce = nonce;
        ws.publicKey = message.publicKey;

        const challengeMsg = {
          type: 'challenges',
          nonce,
          challenges
        };
        ws.send(JSON.stringify(challengeMsg));
        console.log('[Server] Sent', challenges.length, 'challenges');

      } else if (message.type === 'answers') {
        // Step 3: Verify answers and signature
        const startTime = Date.now();

        // Verify signature
        const proofData = JSON.stringify({
          nonce: message.nonce,
          answers: message.answers,
          publicId: message.publicId,
          timestamp: message.timestamp
        });

        let signatureValid = false;
        if (message.signature) {
          const sigHex = typeof message.signature === 'object' 
            ? message.signature.r + message.signature.s
            : message.signature;
          signatureValid = verifySignature(ws.publicKey, proofData, sigHex);
        }

        console.log('[Server] Signature verification:', signatureValid ? 'VALID' : 'INVALID');

        // Verify answers
        let allCorrect = true;
        message.answers.forEach(ans => {
          const challenge = ws.challenges?.find(c => c.id === ans.id);
          if (challenge) {
            const parts = challenge.question.split(' ');
            const a = parseInt(parts[0]);
            const b = parseInt(parts[2]);
            const expected = parts[1] === '+' ? a + b : a - b;
            if (ans.answer !== expected) {
              allCorrect = false;
            }
          }
        });

        const verified = signatureValid && allCorrect;
        const sessionToken = generateSessionToken();

        const resultMsg = {
          type: 'result',
          verified,
          publicId: message.publicId,
          sessionToken,
          verificationTime: Date.now() - startTime
        };

        ws.send(JSON.stringify(resultMsg));
        console.log('[Server] Verification result:', verified ? 'SUCCESS' : 'FAILED');
        console.log('[Server] publicId:', resultMsg.publicId);
        console.log('[Server] sessionToken:', resultMsg.sessionToken);

      } else {
        console.log('[Server] Unknown message type:', message.type);
      }
    } catch (e) {
      console.error('[Server] Error processing message:', e.message);
    }
  });

  ws.on('close', () => {
    console.log('[Server] Client disconnected');
  });
});

server.listen(3000, () => {
  console.log('[Server] AAP WebSocket server listening on port 3000');
  console.log('[Server] Path: /aap');
  console.log('[Server] requireSignature: true');
});
