const WebSocket = require('ws');
const { ec } = require('elliptic');
const fs = require('fs');
const secp256k1 = new ec('secp256k1');

// Generate identity (key pair)
function generateIdentity() {
  const keyPair = secp256k1.genKeyPair();
  return {
    privateKey: keyPair,
    publicKey: keyPair.getPublic('hex'),
    publicId: keyPair.getPublic('hex').substring(0, 16)
  };
}

// Sign data with private key
function sign(privateKey, message) {
  const sig = privateKey.sign(message);
  return {
    r: sig.r.toString(16).padStart(64, '0'),
    s: sig.s.toString(16).padStart(64, '0')
  };
}

// Solve math challenges
function solveChallenges(challenges) {
  return challenges.map(challenge => {
    const parts = challenge.question.split(' ');
    const a = parseInt(parts[0]);
    const b = parseInt(parts[2]);
    const answer = parts[1] === '+' ? a + b : a - b;
    return {
      id: challenge.id,
      answer
    };
  });
}

async function runClient() {
  console.log('[Client] Generating identity...');
  const identity = generateIdentity();
  console.log('[Client] Public ID:', identity.publicId);
  console.log('[Client] Public Key:', identity.publicKey);

  console.log('[Client] Connecting to ws://localhost:3000/aap...');
  const ws = new WebSocket('ws://localhost:3000/aap');

  return new Promise((resolve, reject) => {
    ws.on('open', () => {
      console.log('[Client] Connected');
    });

    ws.on('message', (data) => {
      const message = JSON.parse(data.toString());
      console.log('[Client] Received:', message.type);

      if (message.type === 'handshake') {
        console.log('[Client] Handshake received');
        console.log('[Client] Protocol:', message.protocol, message.version);
        console.log('[Client] requireSignature:', message.requireSignature);

        // Send ready with public key
        ws.send(JSON.stringify({
          type: 'ready',
          publicKey: identity.publicKey
        }));
        console.log('[Client] Sent ready with publicKey');

      } else if (message.type === 'challenges') {
        console.log('[Client] Received', message.challenges.length, 'challenges');

        // Solve challenges
        const answers = solveChallenges(message.challenges);
        console.log('[Client] Answers:', answers);

        // Create proof data and sign
        const timestamp = Date.now();
        const proofData = JSON.stringify({
          nonce: message.nonce,
          answers,
          publicId: identity.publicId,
          timestamp
        });

        const signature = sign(identity.privateKey, proofData);
        console.log('[Client] Signed proof data');

        // Send answers with signature
        ws.send(JSON.stringify({
          type: 'answers',
          nonce: message.nonce,
          answers,
          publicId: identity.publicId,
          timestamp,
          signature
        }));
        console.log('[Client] Sent answers with signature');

      } else if (message.type === 'result') {
        console.log('[Client] Verification result received');
        console.log('[Client] Verified:', message.verified);
        console.log('[Client] Public ID:', message.publicId);
        console.log('[Client] Session Token:', message.sessionToken);
        console.log('[Client] Verification Time:', message.verificationTime, 'ms');

        // Write summary file
        const summary = {
          timestamp: new Date().toISOString(),
          verified: message.verified,
          publicId: message.publicId,
          sessionToken: message.sessionToken,
          verificationTimeMs: message.verificationTime,
          protocol: 'AAP',
          version: '3.2.0'
        };

        const summaryText = `AAP Attestation Summary
========================
Timestamp: ${summary.timestamp}
Verified: ${summary.verified}
Public ID: ${summary.publicId}
Session Token: ${summary.sessionToken}
Verification Time: ${summary.verificationTimeMs}ms
Protocol: AAP v3.2.0
========================
${message.verified ? 'SUCCESS: AI agent verified!' : 'FAILED: Verification did not succeed'}
`;

        fs.writeFileSync('attestation_summary.json', JSON.stringify(summary, null, 2));
        fs.writeFileSync('attestation_summary.txt', summaryText);
        console.log('[Client] Summary written to attestation_summary.json and attestation_summary.txt');

        ws.close();
        resolve(summary);
      }
    });

    ws.on('error', (err) => {
      console.error('[Client] WebSocket error:', err.message);
      reject(err);
    });

    ws.on('close', () => {
      console.log('[Client] Connection closed');
    });
  });
}

// Run with retry logic
async function main() {
  let attempts = 0;
  const maxAttempts = 5;

  while (attempts < maxAttempts) {
    try {
      const result = await runClient();
      if (result.verified) {
        console.log('\n[Client] Atttestation complete!');
        return;
      }
    } catch (err) {
      attempts++;
      console.log(`[Client] Attempt ${attempts}/${maxAttempts} failed: ${err.message}`);
      if (attempts < maxAttempts) {
        await new Promise(r => setTimeout(r, 1000));
      }
    }
  }
  console.log('[Client] Failed after all attempts');
}

main().catch(console.error);
